748	function StatusBadge({ status }: { status: string }) {
749	  switch (status) {
750	    case "completed":
751	      return <Badge variant="success" className="capitalize text-xs font-medium">Completed</Badge>;
752	    case "processing":
753	      return <Badge variant="warning" className="capitalize text-xs font-medium">Processing</Badge>;
754	    case "pending":
755	      return <Badge variant="warning" className="capitalize text-xs font-medium">Pending</Badge>;
756	    case "failed":
757	      return <Badge variant="destructive" className="capitalize text-xs font-medium">Failed</Badge>;
758	    default:
759	      return <Badge variant="outline" className="capitalize text-xs font-medium">{status}</Badge>;
760	  }
761	}
